from gpiozero import DigitalOutputDevice
import time
import sys

# GPIO pins for the digital outputs (BCM numbering)
OUTPUT_PINS = {"red": 2, "yellow": 3, "green": 4}


def apply_color(color_name, should_on):
    """Apply a color state to the corresponding GPIO output."""
    # Look up the pin for the requested color
    pin_number = OUTPUT_PINS.get(color_name)
    if pin_number is None:
        raise ValueError("Unknown color: " + color_name)
    # Create or reuse the gpiozero device for the pin
    try:
        device = DigitalOutputDevice(pin_number, active_high=True, initial_value=False)
    except Exception as device_error:
        print("Device error:", color_name, device_error)
        return
    # Apply the requested on/off state
    if should_on:
        device.on()
    else:
        device.off()
    # Report the applied state for the operator
    print("Applied", color_name, "on pin", pin_number, "state", should_on)


def main():
    """Run the color pattern loop on the Raspberry Pi."""
    # Sequence of colors to cycle through
    color_sequence = ["red", "yellow", "green"]
    try:
        while True:
            # Visit each color in turn
            for color_name in color_sequence:
                apply_color(color_name, True)
                # Wait the fixed cycle delay
                time.sleep(60)
                apply_color(color_name, False)
    except KeyboardInterrupt:
        # Allow the operator to stop the loop
        print("Stopping traffic light loop")
    except Exception as loop_error:
        # Report any unexpected error
        print("Loop error:", loop_error)
        sys.exit(1)
    finally:
        # Release the gpiozero devices
        for device in DigitalOutputDevice.objects:
            device.close()


if __name__ == "__main__":
    main()

