import time
import logging
from typing import Optional

try:
    import board
    import busio
    import adafruit_mcp3008
except ImportError:
    # Fallback for environments without hardware
    board = None
    busio = None
    adafruit_mcp3008 = None

# Logging setup for the ADC reader
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("mcp3008_adc")

# Constants for the ADC configuration
ADC_VOLTAGE_REFERENCE = 3.3
ADC_MAX_VALUE = 1023


def initialize_adc(spi_bus: busio.SPI, chip_select_pin: board.Pin) -> Optional[adafruit_mcp3008.MCP3008]:
    """Initializes the MCP3008 ADC on the given SPI bus and chip select pin."""
    try:
        return adafruit_mcp3008.MCP3008(spi_bus, chip_select_pin)
    except Exception as init_error:
        logger.error(f"Failed to initialize ADC: {init_error}")
        return None


def read_adc_channel(adc_device: adafruit_mcp3008.MCP3008, channel_number: int) -> Optional[int]:
    """Reads the raw value from the specified ADC channel."""
    if adc_device is None:
        logger.error("ADC device is not initialized.")
        return None
    if not 0 <= channel_number <= 7:
        logger.error(f"Invalid ADC channel: {channel_number}")
        return None
    try:
        raw_value = adc_device.read(channel_number)
        return raw_value
    except Exception as read_error:
        logger.error(f"Failed to read ADC channel {channel_number}: {read_error}")
        return None


def convert_to_voltage(raw_value: int) -> float:
    """Converts a raw ADC reading to a voltage value."""
    if raw_value is None:
        return None
    return (raw_value / ADC_MAX_VALUE) * ADC_VOLTAGE_REFERENCE


def main():
    """Main function to sample and log ADC readings."""
    if board is None or busio is None or adafruit_mcp3008 is None:
        logger.error("Hardware dependencies not available. Exiting.")
        return

    spi_bus = None
    chip_select_pin = None
    adc_device = None

    try:
        # Initialize SPI and chip select pin
        spi_bus = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        chip_select_pin = board.D5

        # Initialize the ADC
        adc_device = initialize_adc(spi_bus, chip_select_pin)

        if adc_device is None:
            return

        # Read and log voltage readings from the ADC
        for reading_index in range(25):
            raw_value = read_adc_channel(adc_device, 0)
            if raw_value is not None:
                voltage_value = convert_to_voltage(raw_value)
                if voltage_value is not None:
                    logger.info(f"ADC Reading {reading_index + 1}: {voltage_value:.3f}V")
            time.sleep(0.25)

    except KeyboardInterrupt:
        logger.info("ADC readings stopped by user.")
    except Exception as main_error:
        logger.error(f"An unexpected error occurred: {main_error}")
    finally:
        # Ensure resources are released
        if spi_bus is not None:
            spi_bus.deinit()
        if chip_select_pin is not None:
            chip_select_pin.deinit()
        if adc_device is not None:
            adc_device = None


if __name__ == "__main__":
    main()

