    adafruit_mcp3008 = None

# Logging for the ADC reader
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("adc_reader")

# ADC configuration for the Raspberry Pi
ADC_BUS_NUMBER = 0
ADC_DEVICE_NUMBER = 0
SAMPLE_INTERVAL_SECONDS = 300
SAMPLE_COUNT = 5


def setup_adc():
    """Initialize the MCP3008 ADC handle."""
    # Skip hardware setup if no hardware is available
    if adafruit_mcp3008 is None:
        return None
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA, ADC_BUS_NUMBER)
        return adafruit_mcp3008.MCP3008(i2c_bus, ADC_DEVICE_NUMBER)
    except Exception as setup_error:
        logger.error("ADC setup failed: %s", setup_error)
        return None


def read_adc_channel(adc_handle, channel_index):
    """Read a raw value from one MCP3008 channel."""
    # Reject channels outside the valid range
    if adc_handle is None or channel_index < 0 or channel_index > 7:
        return None
    try:
        raw_value = adc_handle.read_adc(channel_index, gain=1)
        return raw_value
    except Exception as read_error:
        logger.error("Channel %s read failed: %s", channel_index, read_error)
        return None


def main():
    """Sample the ADC and report the readings."""
    adc_handle = setup_adc()
    try:
        for sample_index in range(SAMPLE_COUNT):
            raw_value = read_adc_channel(adc_handle, 0)
            if raw_value is not None:
                logger.info("ADC reading %s: %s", sample_index, raw_value)
            time.sleep(SAMPLE_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        logger.info("ADC sampling stopped")
    finally:
        # Release the I2C bus on exit
        if adc_handle is not None and board is not None:
            board.I2C().deinit()


