        humidity_value = DHT_DEVICE.humidity
        if temperature_value is not None and humidity_value is not None:
            return "{0:0.1f}C {1:0.1f}%".format(temperature_value, humidity_value)
        return "INVALID"
    except RuntimeError as sensor_error:
        # Report any sensor read failure
        return "ERROR: {0}".format(sensor_error.args[0])


def report_state(state_text):
    """Print the DHT22 state to standard output."""
    # Present the measured state to the operator
    print("DHT22 state: {0}".format(state_text))


if __name__ == "__main__":
    # Run a fixed number of read cycles on the Raspberry Pi
    try:
        for cycle_index in range(3):
            current_state = read_dht_state()
            report_state(current_state)
            time.sleep(5)
    except KeyboardInterrupt:
        # Allow the operator to stop the monitor
        print("DHT22 monitor stopped")
    finally:
        # Release the DHT22 sensor hardware
        DHT_DEVICE.exit()
